const CACHE="bauru-sul-no-history-window-v2",SHELL=["/","/manifest.webmanifest","/app-icon.svg","/app-icon-192.png","/app-icon-512.png"];
self.addEventListener("install",event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(SHELL)).then(()=>self.skipWaiting())));
self.addEventListener("activate",event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));
self.addEventListener("fetch",event=>{if(event.request.method!=="GET"||event.request.url.includes("/api/"))return;const url=new URL(event.request.url);const appCode=url.origin===self.location.origin&&(event.request.mode==="navigate"||/\.(?:js|css)$/.test(url.pathname));event.respondWith(fetch(event.request,appCode?{cache:"no-cache"}:undefined).then(response=>{const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));return response}).catch(()=>caches.match(event.request).then(cached=>cached||caches.match("/"))))});
